mapper.select:
select
a.id, a.task_wcs_id, a.start_position, a.purpose_position, a.send_data, a.accept_data,
a.interface_type,a.main_task_no ,a.wcs_type , a.order_id, a.status, a.remark, a.create_time,
b.task_type ,b.task_no , b.task_status , b.tray_code
from t_task_wcs_record a
left join t_task_wcs b on a.task_wcs_id = b.id

    inner join sys_user u on u.user_name = a.create_by and u.status = '0'
    inner join sys_dept d on u.dept_id = d.dept_id and d.status = '0'


    a.del_flag = '0'
    and a.task_wcs_id = #{taskWcsId}
    and a.start_position =
        #{startPosition}

    and a.purpose_position =
        #{purposePosition}

    and a.send_data = #{sendData}
    and a.accept_data = #{acceptData}
    and a.order_id = #{orderId}
    and a.status = #{status}
    and a.main_task_no = #{mainTaskNo}


${params.dataScope}

select
a.id, a.task_wcs_id, a.send_data, a.accept_data,
a.interface_type,a.main_task_no ,a.wcs_type , a.order_id, a.status, a.create_time,
b.task_type ,b.task_no , b.task_status , b.tray_code,
if(b.task_type= '5',tl.name,tl3.name)as startPosition,
if(b.task_type= '5',tl2.name,tl3.name)as purposePosition
from t_task_wcs_record a
left join t_task_wcs b on a.task_wcs_id = b.id
left join t_location tl on b.start_position = tl.code
left join t_location tl2 on b.purpose_position = tl2.code
left join t_location tl3 on b.location_id = tl3.id

    a.del_flag = '0' and b.tray_id = #{trayId}
    and a.task_wcs_id = #{taskWcsId}
    and a.start_position =
        #{startPosition}

    and a.purpose_position =
        #{purposePosition}

    and a.send_data = #{sendData}
    and a.accept_data = #{acceptData}
    and a.order_id = #{orderId}
    and a.status = #{status}
    and a.main_task_no = #{mainTaskNo}

order by a.create_time desc
